package com.nirikshan.controller;
import com.nirikshan.dto.AuthRequests.*;import com.nirikshan.dto.AuthResponses.*;import com.nirikshan.model.*;import com.nirikshan.repository.*;import com.nirikshan.security.CurrentUser;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.security.SecureRandom;import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminUserController {private final UserRepository users;private final ZoneRepository zones;private final SecurityInstructionRepository instructions;private final CurrentUser current;private final PasswordEncoder passwords;private final SecureRandom random=new SecureRandom();public AdminUserController(UserRepository u,ZoneRepository z,SecurityInstructionRepository i,CurrentUser c,PasswordEncoder p){users=u;zones=z;instructions=i;current=c;passwords=p;}
 @PostMapping("/users") public CreatedUser create(@Valid @RequestBody CreateUser r){if(r.role()==UserRole.CITIZEN)throw new IllegalArgumentException("Admins can create SECURITY or ADMIN accounts only");String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmailIgnoreCase(email))throw new IllegalArgumentException("An account already exists for this email");Zone zone=null;if(r.role()==UserRole.SECURITY){if(r.assignedZoneId()==null)throw new IllegalArgumentException("Security accounts require an assigned zone");zone=zones.findById(r.assignedZoneId()).orElseThrow(()->new IllegalArgumentException("Assigned zone was not found"));}String temp=temp();User u=new User();u.setName(r.name().trim());u.setEmail(email);u.setRole(r.role());u.setAssignedZone(zone);u.setCreatedByAdmin(current.get());u.setMustChangePassword(true);u.setPasswordHash(passwords.encode(temp));users.save(u);return new CreatedUser(AuthController.info(u),temp);}
 @GetMapping("/users") public List<UserInfo> list(){return users.findAllByOrderByCreatedAtDesc().stream().map(AuthController::info).toList();}
 @DeleteMapping("/users/{id}") public void deactivate(@PathVariable Long id){User u=users.findById(id).orElseThrow(()->new IllegalArgumentException("User not found"));if(u.getId().equals(current.get().getId()))throw new IllegalArgumentException("You cannot deactivate your own account");u.setActive(false);users.save(u);}
 @PostMapping("/instructions") public InstructionInfo instruction(@Valid @RequestBody Instruction r){SecurityInstruction i=new SecurityInstruction();i.setMessage(r.message());i.setCreatedBy(current.get());if(r.targetZoneId()!=null)i.setTargetZone(zones.findById(r.targetZoneId()).orElseThrow(()->new IllegalArgumentException("Zone not found")));if(r.targetSecurityUserId()!=null){User u=users.findById(r.targetSecurityUserId()).orElseThrow(()->new IllegalArgumentException("Security user not found"));if(u.getRole()!=UserRole.SECURITY)throw new IllegalArgumentException("Instructions can target security personnel only");i.setTargetSecurityUser(u);}instructions.save(i);return new InstructionInfo(i.getId(),i.getMessage(),i.getTargetZone()==null?null:i.getTargetZone().getId(),i.getTargetSecurityUser()==null?null:i.getTargetSecurityUser().getId(),i.getCreatedAt());}
 private String temp(){byte[] b=new byte[9];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b)+"!";}}
